logger = BackgroundLogger.Instance()


class Parameters(object):
    """
    Parameter
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def get_parameter(self, **kwargs):
        """
        Function to get parameter
        """
        btssm_version = kwargs.get("btssm_version")
        param_dictionary_path = kwargs.get("param_dictionary_path")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["btssm_version", "param_dictionary_path"]}
        self.oam_tool.get_parameter_dictionary(btssm_version=btssm_version,
                                               param_dictionary_path=param_dictionary_path,
                                               **kwargs)

